%[text] # Aufgabe 2.2: Künstliche Testbilder erzeugen
%%
%[text] ## a) Zufällige Grauwerte
gleich = uint8(randi([64 255], 100, 100));    % gleichverteilt in [64;255]

mu    = 128;
sigma = 30;
normal = uint8(mu + sigma * randn(100, 100));  % normalverteilt

figure %[output:76b7cd9e]
subplot(1,2,1) %[output:76b7cd9e]
imshow(gleich) %[output:76b7cd9e]
title('gleichverteilt') %[output:76b7cd9e]

subplot(1,2,2) %[output:76b7cd9e]
imshow(normal) %[output:76b7cd9e]
title('normalverteilt') %[output:76b7cd9e]
%%
%[text] Mittelwert und Varianz variieren:
mus    = [64 128 192];
sigmas = [10 30 80];

figure %[output:395bd746]
k = 1;
for i = 1:3 %[output:group:29600dad]
    for j = 1:3
        bild = uint8(mus(j) + sigmas(i) * randn(100, 100));
        subplot(3, 3, k) %[output:395bd746]
        imshow(bild)
        title(['mu=' num2str(mus(j)) ', sigma=' num2str(sigmas(i))])
        k = k + 1;
    end
end %[output:group:29600dad]
%[text] Mittelwert größer → Bild heller, kleiner → dunkler.
%[text] Varianz größer → mehr Kontrast/Rauschen, kleiner → fast einheitlich grau.
%[text] Bei großer Varianz werden viele Werte bei 0 bzw. 255 abgeschnitten (uint8).
%%
%[text] ## c) Rauschen mit imnoise
grau = rgb2gray(imread('Auge.jpg'));

gauss   = imnoise(grau, 'gaussian');
poisson = imnoise(grau, 'poisson');
saltpep = imnoise(grau, 'salt & pepper');
speckle = imnoise(grau, 'speckle');

figure %[output:1c4acf35]
montage({gauss, poisson, saltpep, speckle}, 'Size', [2 2]) %[output:1c4acf35]
title('Gauss, Poisson, Salt & Pepper, Speckle') %[output:1c4acf35]

